        GM_CALLV(0x802D17E8u, 0x802D12E0u, 0);
        R(0) = gm_u16(R(31) + 52);
        FB(1, LF(R(2) - 15116)); FB(0, LF(R(2) - 15120));
        R(0) = R(0) & 0xFFFE;
