    R(3) = 0x1000000u;
    R(5) = R(3) - 1;
    R(9) = gm_u8(R(2) - 13392); R(8) = gm_u8(R(4) + 1);
    R(10) = 0;
    R(7) = gm_u8(R(4) + 2); R(6) = gm_u8(R(4) + 3);
    R(4) = gm_u32(R(2) - 15992); R(3) = gm_u16(R(2) - 15988); R(0) = gm_u8(R(2) - 15986);
    gm_set_u8(R(31) + 24, 0); gm_set_u8(R(31) + 25, (uint8_t)R(9)); gm_set_u8(R(31) + 26, (uint8_t)R(8));
    gm_set_u8(R(31) + 27, (uint8_t)R(7)); gm_set_u8(R(31) + 28, (uint8_t)R(6));
    gm_set_u32(R(31) + 32, R(5)); gm_set_u32(R(31) + 36, R(4));
    gm_set_u16(R(31) + 40, (uint16_t)R(3)); gm_set_u8(R(31) + 42, (uint8_t)R(0));
    R(0) = lr;
