    R(5) = gm_u32(R(4));
    if (cmps(ctx, (int32_t)R(5), 0) != 0) gm_set_u32(R(5), R(0));
    R(5) = gm_u32(R(4));
    FB(1, LF(R(3) + 12));
    int c = cmps(ctx, (int32_t)R(5), 0);
    FB(0, LF(R(3) + 8));
