/* (an animation frame's key value, cached: the same frame (+24) as last time gives +26; else the
   key table on +20's list whose [first, last] holds the frame (0x8022C120), 0xFFFF when none;
   then 0x8022C1F0 with it, 0xFFFF meaning +20's default) */
static void anm_frame_cached(GM_CTX) {
    GM_FN(0x8022BF80); GM_NV_KEEP; GM_LR_KEEP;
    uint32_t lr = ctx->lr;
    R(31) = R(4); R(30) = R(3);
    R(0) = gm_u16(R(3) + 24);
    if (cmpu(ctx, R(5), R(0)) == 0) { R(5) = gm_u16(R(3) + 26); goto have; }
    gm_set_u16(R(3) + 24, (uint16_t)R(5));
    R(4) = gm_u32(R(3) + 20); R(4) = gm_u32(R(4) + 16);
    goto test;
body:
    R(0) = gm_u16(R(4));
    if (cmpu(ctx, R(0), R(5)) <= 0) {
        R(0) = gm_u16(R(4) + 2);
        if (cmpu(ctx, R(5), R(0)) <= 0) {
            R(3) = R(30);
            GM_CALLV(0x8022BFE0u, 0x8022C120u, 0);
            gm_set_u16(R(30) + 26, (uint16_t)R(3));
            R(5) = R(3) & 0xFFFF;
            goto have;
        }
    }
    R(4) = gm_u32(R(4) + 8);
test:
    if (cmps(ctx, (int32_t)R(4), 0) != 0) { GM_LOOP(); goto body; }
    R(4) = 0x10000u; R(0) = R(4) - 1;
    gm_set_u16(R(3) + 26, (uint16_t)R(0));
    R(5) = R(0) & 0xFFFF;
have:
    { int c = cmpu(ctx, R(5), 0xFFFF);
      R(3) = R(30); R(4) = R(31);
      if (c == 0) { R(5) = gm_u32(R(30) + 20); R(5) = gm_u16(R(5) + 2); } }
    R(5) = R(5) & 0xFFFF;
    GM_CALLV(0x8022C02Cu, 0x8022C1F0u, 0);
    R(0) = lr;
}
/* (copy r5 bytes (a multiple of 32) from r4 to r3 through f0, 128 at a time, then 32 at a time) */
static void fp_copy32(GM_CTX) {
    R(5) = R(5) >> 5;
    if (cmps(ctx, (int32_t)R(5), 0) == 0) return;
    R(0) = R(5) >> 2;
    int c = cmps(ctx, (int32_t)R(0), 0);
    ctx->ctr = R(0);
    if (c != 0) {
        for (;;) {
            for (int i = 0; i < 128; i += 8) { ctx->f[0].u = ld64(base, R(4) + i); st64(base, R(3) + i, ctx->f[0].u); }
            R(4) = R(4) + 128; R(3) = R(3) + 128;
            if (--ctx->ctr == 0) break;
            GM_LOOP();
        }
        R(5) = R(5) & 3;
        if (cmps(ctx, (int32_t)R(5), 0) == 0) return;
    }
    ctx->ctr = R(5);
    for (;;) {
        for (int i = 0; i < 32; i += 8) { ctx->f[0].u = ld64(base, R(4) + i); st64(base, R(3) + i, ctx->f[0].u); }
        R(4) = R(4) + 32; R(3) = R(3) + 32;
        if (--ctx->ctr == 0) break;
        GM_LOOP();
    }
}
